557	const computeRelations = async (
558	  plugin: DiscourseGraphPlugin,
559	  file: TFile,
560	): Promise<GroupedRelation[]> => {
561	  const fileCache = plugin.app.metadataCache.getFileCache(file);
562	  if (!fileCache?.frontmatter) return [];
563	
564	  const activeNodeTypeId = fileCache.frontmatter.nodeTypeId as string;
565	  if (!activeNodeTypeId) return [];
566	
567	  const nodeInstanceId = await getNodeInstanceIdForFile(plugin, file);
568	  if (!nodeInstanceId) return [];
569	
570	  const relations = await getRelationsForNodeInstanceId(plugin, nodeInstanceId);
571	  const result = new Map<string, GroupedRelation>();
572	
573	  const acceptedRelationTypes =
574	    plugin.settings.relationTypes.filter(isAcceptedSchema);
575	  const acceptedDiscourseRelations =
576	    plugin.settings.discourseRelations.filter(isAcceptedSchema);
577	
578	  for (const relationType of acceptedRelationTypes) {
579	    const matchingRelations = acceptedDiscourseRelations.filter(
580	      (relation) =>
581	        (relation.sourceId === activeNodeTypeId ||
582	          relation.destinationId === activeNodeTypeId) &&
583	        relation.relationshipTypeId === relationType.id,
584	    );
585	    for (const typeLevelRelation of matchingRelations) {
586	      const isSource = typeLevelRelation.sourceId === activeNodeTypeId;
587	      const key = `${relationType.id}-${isSource}`;
588	
589	      if (!result.has(key)) {
590	        result.set(key, {
591	          key,
592	          label: isSource ? relationType.label : relationType.complement,
593	          isSource,
594	          relationTypeId: relationType.id,
595	          linkedFiles: [],
596	        });
597	      }
598	
599	      const group = result.get(key)!;
600	      for (const relation of relations) {
601	        if (relation.type !== relationType.id) continue;
602	        const otherId = getRelationCounterpartId({
603	          relation,
604	          nodeInstanceId,
605	          isSource,
606	        });
607	        if (!otherId) continue;
608	
609	        const linkedFile = getFileForNodeInstanceId(plugin, otherId);
610	        if (
611	          linkedFile &&
612	          !group.linkedFiles.some(({ path }) => path === linkedFile.path)
613	        ) {
614	          group.linkedFiles.push(linkedFile);
615	        }
616	      }
617	    }
618	  }
619	
620	  // Only show relation types that have relation instances
621	  return Array.from(result.values()).filter(
622	    (group) => group.linkedFiles.length > 0,
623	  );
624	};
625	
626	const getRelationCounterpartId = ({
627	  relation,
628	  nodeInstanceId,
629	  isSource,
630	}: {
631	  relation: { source: string; destination: string };
632	  nodeInstanceId: string;
633	  isSource: boolean;
634	}): string | null => {
635	  if (isSource) {
636	    return relation.source === nodeInstanceId ? relation.destination : null;
637	  }
638	
639	  return relation.destination === nodeInstanceId ? relation.source : null;
640	};

